input.command:
agent-browser eval "(async () => {
  const likeBtn = document.querySelector(\"[data-testid='like-1']\");
  const likesCount = document.querySelector(\"[data-testid='likes-1']\");
  if (!likeBtn || !likesCount) return { error: 'Elements not found' };
  const before = parseInt(likesCount.textContent);
  const target = before + 1;
  const startTime = performance.now();
  likeBtn.click();
  let changedWithin150ms = false;
  let elapsedAtChange = -1;
  while (performance.now() - startTime < 150) {
    if (parseInt(likesCount.textContent) === target) {
      changedWithin150ms = true;
      elapsedAtChange = performance.now() - startTime;
      break;
    }
    await new Promise(r => setTimeout(r, 5));
  }
  const waitRemaining = 800 - (performance.now() - startTime);
  if (waitRemaining > 0) await new Promise(r => setTimeout(r, waitRemaining));
  const finalValue = parseInt(likesCount.textContent);
  const remainedCorrect = (finalValue === target);
  return {
    before,
    target,
    changedWithin150ms,
    elapsedAtChange,
    finalValue,
    remainedCorrect,
    pass: changedWithin150ms && remainedCorrect
  };
})()"
